//! File storage for uploads: local disk, or S3-compatible with the `s3` feature.
//!
//! Keys are generated by the framework (`yyyy/mm/<uuid>.<ext>`), never taken
//! from user input, and every driver re-validates them. Downloads always go
//! through the application (no presigned URLs), so authorization and response
//! headers apply to every byte served.

mod local;
#[cfg(feature = "s3")]
mod s3;

pub use local::*;

use std::path::{Path, PathBuf};
use std::sync::Arc;

use async_trait::async_trait;
use axum::body::Body;
use serde::Deserialize;

/// Why a storage operation failed.
#[derive(Debug, thiserror::Error)]
pub enum StorageError {
    /// No object under that key.
    #[error("object not found")]
    NotFound,
    /// The key or the path it maps to is not acceptable (e.g. a symlink).
    #[error("refused storage path: {0}")]
    Refused(String),
    /// I/O or backend failure.
    #[error("storage failure: {0}")]
    Backend(String),
}

impl From<std::io::Error> for StorageError {
    fn from(err: std::io::Error) -> Self {
        if err.kind() == std::io::ErrorKind::NotFound { Self::NotFound } else { Self::Backend(err.to_string()) }
    }
}

impl From<StorageError> for crate::AppError {
    fn from(err: StorageError) -> Self {
        match err {
            StorageError::NotFound => Self::NotFound,
            other => Self::internal(other),
        }
    }
}

/// A validated object key: `yyyy/mm/<uuid>.<ext>`, lowercase ASCII only.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct StorageKey(String);

impl StorageKey {
    /// A new key for an object with extension `ext` (from a fixed MIME map).
    pub fn generate(ext: &str) -> Result<Self, StorageError> {
        let now = chrono::Utc::now();
        Self::parse(&format!("{}/{}/{}.{ext}", now.format("%Y"), now.format("%m"), uuid::Uuid::now_v7()))
    }

    /// Validates a stored key.
    pub fn parse(key: &str) -> Result<Self, StorageError> {
        let refused = || StorageError::Refused(format!("invalid key `{}`", key.escape_debug()));
        let parts: Vec<&str> = key.split('/').collect();
        let [year, month, file] = parts.as_slice() else { return Err(refused()) };
        let digits = |s: &str, n: usize| s.len() == n && s.bytes().all(|b| b.is_ascii_digit());
        let (stem, ext) = file.split_once('.').ok_or_else(refused)?;
        let ext_ok = (1..=5).contains(&ext.len()) && ext.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit());
        if !digits(year, 4) || !digits(month, 2) || uuid::Uuid::parse_str(stem).is_err() || stem.len() != 36 || !ext_ok
        {
            return Err(refused());
        }
        Ok(Self(key.to_owned()))
    }

    /// The key as text.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// A storage backend.
#[async_trait]
pub trait Storage: Send + Sync {
    /// Driver name stored with each object (`local`, `s3`).
    fn disk(&self) -> &'static str;
    /// Where uploads are staged before `put_file` (same filesystem as the
    /// objects for `local`, so the final move is a rename).
    fn staging_dir(&self) -> PathBuf;
    /// Stores the file at `file` under `key`.
    async fn put_file(&self, key: &StorageKey, file: &Path, content_type: &str) -> Result<(), StorageError>;
    /// The object's bytes and length.
    async fn open(&self, key: &StorageKey) -> Result<(Body, u64), StorageError>;
    /// Deletes the object; deleting a missing object succeeds.
    async fn delete(&self, key: &StorageKey) -> Result<(), StorageError>;
    /// Whether the object exists.
    async fn exists(&self, key: &StorageKey) -> Result<bool, StorageError>;
    /// Removes staging and partial files older than `older_than` (uploads
    /// interrupted by a crash or a cancelled request); returns how many.
    async fn sweep(&self, older_than: std::time::Duration) -> Result<u64, StorageError> {
        let _ = older_than;
        Ok(0)
    }
}

/// `[storage]` settings.
#[derive(Debug, Clone, Deserialize)]
#[serde(default)]
pub struct StorageConfig {
    /// `local` or `s3`.
    pub disk: String,
    /// Root directory of the `local` disk.
    pub root: PathBuf,
    /// Largest accepted upload, in bytes.
    pub max_upload_bytes: u64,
    /// Largest accepted image, in pixels (width × height).
    pub max_pixels: u64,
    /// Uploads processed at the same time; more answer 429.
    pub max_concurrent_uploads: usize,
    /// MIME types accepted for upload (SVG, HTML, XML and scripts are always refused).
    pub allowed_types: Vec<String>,
    /// S3-compatible bucket (`disk = "s3"`); credentials come from `AWS_*` variables.
    pub s3: S3Config,
}

/// S3-compatible bucket settings.
#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
pub struct S3Config {
    /// Bucket name.
    pub bucket: String,
    /// Region (default `us-east-1`).
    pub region: Option<String>,
    /// Endpoint for S3-compatible services (MinIO, R2, …).
    pub endpoint: Option<String>,
    /// Allow plain HTTP endpoints (local MinIO only).
    pub allow_http: bool,
}

impl Default for StorageConfig {
    fn default() -> Self {
        Self {
            disk: "local".into(),
            root: PathBuf::from("storage/app"),
            max_upload_bytes: 10 * 1024 * 1024,
            max_pixels: 40_000_000,
            max_concurrent_uploads: 4,
            allowed_types: ["image/png", "image/jpeg", "image/gif", "image/webp", "application/pdf"]
                .map(String::from)
                .to_vec(),
            s3: S3Config::default(),
        }
    }
}

/// Binds the configured storage (`[storage]`) as `Arc<dyn Storage>`, and the
/// [`StorageConfig`]. Boot fails on a misconfigured disk.
pub struct StorageProvider;

impl crate::ServiceProvider for StorageProvider {
    fn register(&self, app: &mut crate::AppBuilder) {
        let config: StorageConfig =
            app.config().section("storage").unwrap_or_else(|e| panic!("invalid [storage] configuration: {e}"));
        let storage = connect(&config).unwrap_or_else(|e| panic!("storage unavailable: {e}"));
        app.bind(storage);
        app.bind(config);
    }
}

/// The bound storage of `state` (see [`StorageProvider`]).
pub fn of(state: &crate::AppState) -> Option<Arc<dyn Storage>> {
    state.service::<Arc<dyn Storage>>().map(|s| s.as_ref().clone())
}

/// Builds the configured storage.
pub fn connect(config: &StorageConfig) -> Result<Arc<dyn Storage>, StorageError> {
    match config.disk.as_str() {
        "local" => Ok(Arc::new(LocalStorage::new(&config.root)?)),
        #[cfg(feature = "s3")]
        "s3" => Ok(Arc::new(s3::S3Storage::new(&config.s3)?)),
        other => Err(StorageError::Backend(format!(
            "unknown storage disk `{other}` (`local`, or `s3` with the `s3` feature)"
        ))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keys_are_generated_and_validated() {
        let key = StorageKey::generate("png").unwrap();
        assert!(StorageKey::parse(key.as_str()).is_ok());
        for bad in [
            "",
            "../etc/passwd",
            "2026/10/../../x.png",
            "/2026/10/0199d3a4-1b2c-7d3e-8f40-123456789abc.png",
            "2026/10/0199d3a4-1b2c-7d3e-8f40-123456789abc.PNG",
            "2026/10/0199d3a4-1b2c-7d3e-8f40-123456789abc",
            "2026/10/not-a-uuid.png",
            "2026/1/0199d3a4-1b2c-7d3e-8f40-123456789abc.png",
            "2026/10/0199d3a4-1b2c-7d3e-8f40-123456789abc.p/g",
            "2026/10/x/0199d3a4-1b2c-7d3e-8f40-123456789abc.png",
        ] {
            assert!(StorageKey::parse(bad).is_err(), "{bad:?}");
        }
    }

    #[tokio::test]
    async fn local_storage_sweeps_abandoned_files() {
        let dir = tempfile::tempdir().unwrap();
        let storage = LocalStorage::new(&dir.path().join("app")).unwrap();
        std::fs::write(storage.staging_dir().join("x.upload"), b"x").unwrap();
        assert_eq!(storage.sweep(std::time::Duration::from_secs(3600)).await.unwrap(), 0, "recent files stay");
        assert_eq!(storage.sweep(std::time::Duration::ZERO).await.unwrap(), 1);
        // A staging symlink is refused at boot.
        #[cfg(unix)]
        {
            let other = dir.path().join("other");
            std::fs::create_dir_all(other.join("x")).unwrap();
            std::os::unix::fs::symlink(dir.path(), other.join(STAGING)).unwrap();
            assert!(LocalStorage::new(&other).is_err());
        }
    }

    #[tokio::test]
    async fn local_storage_round_trips_and_refuses_symlinks() {
        use http_body_util::BodyExt;
        let dir = tempfile::tempdir().unwrap();
        let storage = LocalStorage::new(&dir.path().join("app")).unwrap();
        let source = dir.path().join("upload");
        std::fs::write(&source, b"hello").unwrap();
        let key = StorageKey::generate("txt").unwrap();
        storage.put_file(&key, &source, "text/plain").await.unwrap();
        assert!(storage.exists(&key).await.unwrap());
        let (body, len) = storage.open(&key).await.unwrap();
        assert_eq!(len, 5);
        assert_eq!(body.collect().await.unwrap().to_bytes().as_ref(), b"hello");
        storage.delete(&key).await.unwrap();
        storage.delete(&key).await.unwrap();
        assert!(!storage.exists(&key).await.unwrap());
        assert!(matches!(storage.open(&key).await, Err(StorageError::NotFound)));

        // A directory of the key replaced by a symlink to outside the root.
        let outside = dir.path().join("outside");
        std::fs::create_dir_all(&outside).unwrap();
        let year = key.as_str().split('/').next().unwrap();
        let year_dir = dir.path().join("app").join(year);
        std::fs::remove_dir_all(&year_dir).unwrap();
        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(&outside, &year_dir).unwrap();
            assert!(storage.put_file(&key, &source, "text/plain").await.is_err(), "escaping the root is refused");
            assert!(storage.open(&key).await.is_err());
            assert!(std::fs::read_dir(&outside).unwrap().next().is_none(), "nothing written outside the root");
        }
    }
}
